window.HARDTRP.receive("260944",[[260945,"2026-10-08T08:44:06",9,"Начало темы.\n\n@Pit_d12 — Дм этой темы.",260944,null],[261052,"2026-10-08T10:18:01",59,"@STR_V_Alekseev Fantomas   @iakukot Думаю, сегодня где-то ближе к вечеру можно начать и быстренько закончить нормально вам?",260944,null],[261232,"2026-10-08T14:11:47",58,"//если начало в 6 по мск или после 6 то без проблем",261052,null],[261346,"2026-10-08T16:09:54",59,"//Значит через два часа ты готов на побегушках быть",261232,null],[261348,"2026-10-08T16:13:02",58,"//ага",261346,null],[261350,"2026-10-08T16:13:44",58,"//а я же щяс фастом закуп могу сделать?",260944,null],[261355,"2026-10-08T16:16:02",59,"//пока даже начала не былo",260944,null],[261434,"2026-10-08T17:09:53",59,"// @STR_V_Alekseev Fantomas вам нормально начать через 1 час? Когда появится я ку",260944,null],[261713,"2026-10-08T18:06:02",58,"//так ну я готов",260944,null],[261767,"2026-10-08T18:16:18",8,"/здесь",261434,null],[261771,"2026-10-08T18:16:32",38,"// Ща, Сумрак уйдет из одной лкации",260944,null],[261791,"2026-10-08T18:19:40",38,"// Все, сумрак на месте",260944,null],[261796,"2026-10-08T18:19:57",58,"//ждем яму выходит",260944,null],[261797,"2026-10-08T18:20:06",38,"// Давай сюда @Pit_d12",260944,null],[261802,"2026-10-08T18:20:52",59,"Вы — команда искателей приключений, согласившихся помочь торговцу Табину. Ваша цель — получить у алхимика зелье сопротивления. Получив карту, вы оказываетесь в густом и дремучем лесу, где замечаете избушку с дымом и светом.",260944,null],[261827,"2026-10-08T18:23:40",38,"Юноша 23 лет с седыми волосами и ростом 175 см. Носит плащ-пальто и маску на лице. За маской имеет довольно красивое лицо, или ужасное, не понятно. Носит брюки и ботинки.\nСумрак шел все время в своих мыслях и нес фонарь перед собой, чтобы не наступить на что-то своей случайностью.\n Не заметив избушку юноша продолжил идти, смотря в пол.",260944,null],[261837,"2026-10-08T18:24:57",58,"*михуил используя заговор свет прыгал но своем скакуне к избушке",260944,null],[261839,"2026-10-08T18:25:07",8,"Майа в полёте льнула к кронам и приглядывалась, как индеец, еле заметная своими двадцатью сантиметрами роста",260944,null],[261845,"2026-10-08T18:25:21",58,"//арт стоит кидать?",261837,null],[261907,"2026-10-08T18:34:55",59,"Вот необычная картина: молодой человек в маске, фея, которая, словно индеец, перемещается в кронах деревьев, и мальчик в наряде горничной на лошади. Они идут, не произнося ни слова.",260944,null],[261912,"2026-10-08T18:35:56",8,"– Эй, план-то у нас есть? *кричит всем*",260944,null],[261918,"2026-10-08T18:37:10",38,"Сумрак поворачивается к фее и говорит.\n— Разве нам не нужно забрать у Алхимика зелье сопротивления и отнести его обратно?\n Юноша осматривает карту, повесив фонарь на свою демоническую руку.",261912,null],[261920,"2026-10-08T18:37:42",58,"*михуил остановив коня \n-а зачем нам план?",261907,null],[261922,"2026-10-08T18:37:50",8,"– Ага, а как уговорим? Вдруг он привередливый?",261918,null],[261927,"2026-10-08T18:38:35",38,"— Думаю договоримся, да и если будет привередлив, то нас трое, а он один...",261922,null],[261940,"2026-10-08T18:40:33",58,"-ну если киданет то судьба его жопки будет вечно горящей",260944,null],[261944,"2026-10-08T18:41:09",8,"– Ладно, пробуем *подняла глаза вверх*",261927,null],[261953,"2026-10-08T18:42:46",59,"Группа отважных искателей приключений приближается к лесной избушке, но пока не может уловить ни звука.",260944,null],[261961,"2026-10-08T18:43:44",8,"– Подождите, вдруг запрётся. Давайте я проведу разведку",260944,null],[261963,"2026-10-08T18:44:14",58,"-как то слишком паникуешь но и ладно валяй",260944,null],[261964,"2026-10-08T18:44:14",59,"//хочешь скрытно провести разведку можешь кидать на скрытность",260944,null],[261969,"2026-10-08T18:45:10",8,"/roll 1d20+3 хочет подсмотреть в окно",260944,null],[261989,"2026-10-08T18:47:34",38,"Сумрак кивнул фее и используя специальный механизм закрыл свет фонаря.",261961,null],[261994,"2026-10-08T18:48:52",59,"Маленькая фея кружится возле окна, без особого труда подавляя свои шумы. За окном она видит старого человека, который лежит и о чём-то размышляет. Его огромная борода свисает до самого пола.",260944,null],[262000,"2026-10-08T18:50:54",8,"*вернулась к своим* \n– Не агрессивен, но устал. Всё в порядке",260944,null],[262005,"2026-10-08T18:51:29",58,"-ну пошлите тогда уже?",260944,null],[262006,"2026-10-08T18:51:51",38,"Сумрак подходит к двери и стучит в неё",260944,null],[262011,"2026-10-08T18:52:58",8,"*спряталась за его спиной (Сумрака)*",262006,null],[262015,"2026-10-08T18:53:22",58,"*спряталась за ее спиной :3*",262011,null],[262016,"2026-10-08T18:53:55",59,"— Кто там стучится в этом глухом лесу? Спина болит, открывай дверь, она не заперта.\n*Из-за двери доносится хриплый старческий голос, сопровождаемый шуршанием бороды.*",262006,null],[262021,"2026-10-08T18:54:54",38,"Сумрак открывает дверь и говорит.\n— Здравствуйте, меня и моих товарищей отправили от торговца Табина и наша задача взять у вас что-то...",262016,null],[262025,"2026-10-08T18:55:57",8,"– Необязательно силой, кстати. Можем договориться или заплатить немного",262021,null],[262028,"2026-10-08T18:58:01",59,"А вы от этого ушлого тобтна, внучки и внучки., хорошо,хорошо, что вы пришли, старость не радость, поможете в 3 делах моих, я вам бесплатно сварю это зелье, сопротивление может.\n*Старичок с тростью и посохом в руках говорит хриплым голосом, который выдаёт его возраст*",260944,null],[262032,"2026-10-08T18:59:20",58,"-с какиеми вещями помоч?",260944,null],[262035,"2026-10-08T18:59:38",38,"— Что от нас требуется?\n Поинтересовался Сумрак",262028,null],[262040,"2026-10-08T19:02:07",59,"– Хорошо, что вы спросили, мой белобрысый внучок. У меня немного болит спина, не могли бы вы собрать для меня…\n*Из своего кармашка протягивает вам бумажечку, в которой написан список:\nгорсть радужного клевера и дюжина шапочек гриба кровянка и 2 штуки белых лавровых кустарников",260944,null],[262041,"2026-10-08T19:03:07",38,"— Ох... И где нам именно их искать?\n Спросил Сумрак взяв список.\n— И как нам понять, что это именно то, что мы ищем?",262040,null],[262042,"2026-10-08T19:03:45",8,"– Нет ли рисунков растений, господин?",262040,null],[262044,"2026-10-08T19:07:46",59,"Ох, юные дарование, как вы можете не разбираться в травках, хорошо уж расскажу вам.\nРадужный клевер прирастает в тёмных закоулках и переливается цветом радуги и излучает необычную ауру частиц энергии.\nА а грипп кровянка — это необычный грипп, у которого стекает, как капли кровавых, россыпью росы, которая скапливается в землях, особый энергетический узел.\nА белые лавровые кустарники имеют необычную пушистую белую структуру, которая ничем не спутаешь",260944,null],[262045,"2026-10-08T19:08:20",59,"— Я полагаю, что на западе, дорогая, вы сможете найти необходимые травы или что-то, что будет полезно лично вам. Всё зависит от вашей удачи, наблюдательности, знаний о травах и ваших способностей. Также важно, как вы справитесь с моим первым поручением и двумя оставшимися.",260944,null],[262046,"2026-10-08T19:09:38",58,"-хм а может бытьнам разделиться и быстренько все добыть ведь задача не звучит на 3",260944,null],[262047,"2026-10-08T19:09:45",38,"— А какие поручения?\nСпросил Сумрак",260944,null],[262052,"2026-10-08T19:12:14",8,"– Разделение грозит бедой",262046,null],[262053,"2026-10-08T19:12:15",59,"– Внучок, не спеши с выводами. Пожалуйста, выполни моё первое поручение и помоги мне с двумя оставшимися. Если вы всё сделаете хорошо, возможно, я дам вам что-нибудь в награду довесок. И ещё, лучше вам делать всё вместе. Вдруг кому-то из вас понадобятся навыки или кто-то сможет защитить вас в случае опасности.",262047,null],[262056,"2026-10-08T19:13:12",58,"ты думаешь траву собирать надо всем троим на 1 месте?",262052,null],[262058,"2026-10-08T19:14:04",8,"– И в траве клещи водятся. Надо быть наготове",262056,null],[262059,"2026-10-08T19:14:54",38,"Сумрак кивает и развернувшись идет в сторону запада.\n— До свидания, дедушка...",260944,null],[262060,"2026-10-08T19:14:55",59,"— Маленькая внучка дело говорит всякое, может быть, во время сбора травы лучше уж быть вместе, когда вы троица неопытная, вдруг вы покалечите травку. Не из-за осторожности вашей юной поспешности.",262058,null],[262063,"2026-10-08T19:18:09",59,"*Вы, вероятно, уже приняли решение, выслушав мудрые советы старших. Выходите на улицу с чёткой целью?*",260944,null],[262065,"2026-10-08T19:19:20",58,"*михуил вышел на улицу и спрашивает *\n-куда пойдем с начало",260944,null],[262075,"2026-10-08T19:24:06",8,"– За клевером?",260944,null],[262077,"2026-10-08T19:24:26",58,"-ну давайте за клевером",260944,null],[262099,"2026-10-08T19:29:37",59,"*Наши отважные друзья направляются в путь по западной части леса! Они ищут клевер, чтобы приручить старого пса. Только представьте, какие испытания ждут их впереди! (Прокиньте на выживание кто-то или совместный)",262075,null],[262102,"2026-10-08T19:30:54",38,"// Дайте помощь",262099,null],[262104,"2026-10-08T19:31:11",38,"/r +d20+4 Выживание с помощью",260944,null],[262110,"2026-10-08T19:32:03",38,"Сумрак впервые осматривается по сторонам, что-то ища, как делали его недавние друзья Госпожа Аврора, Мисс Дампир и Мистер Эльф.",260944,null],[262112,"2026-10-08T19:32:40",58,"//мне интересно а когда вы поймете что михуил не эльф",260944,null],[262113,"2026-10-08T19:32:45",59,"*Мальчик в маске, следуя за запахом и ароматом различных растительных ингредиентов, выходит на поляну, полную растений — мечту травника.*",260944,null],[262114,"2026-10-08T19:33:08",38,"// Я про своих прошлых товарищей",262112,null],[262115,"2026-10-08T19:33:16",58,"//блять",262114,null],[262118,"2026-10-08T19:33:35",8,"*пыльца, много вкусной пыльцы, носится в голове у Майи*",260944,null],[262119,"2026-10-08T19:33:37",38,"// У меня инет говно",262113,null],[262120,"2026-10-08T19:34:08",59,"//там просто полянка усеяна разной магической травкой",262119,null],[262121,"2026-10-08T19:34:12",58,"-хм ну тут мы должны по ощющениям все найти",262113,null],[262122,"2026-10-08T19:34:15",38,"— Ого... Не думал что это так легко...\n Ответил Сумрак и начал искать нужные травы, параллельно собирая другие",262113,null],[262124,"2026-10-08T19:35:50",58,"*михуил акуратно начинает тоже собюирать",260944,null],[262125,"2026-10-08T19:36:33",59,"// Хорошо может ли мне каждый просто чистый д 20 кинуть и параллельно описывать каким образом это вы собирайте",260944,null],[262126,"2026-10-08T19:36:44",58,"/r",260944,null],[262128,"2026-10-08T19:37:04",58,"//везунчик",260944,null],[262130,"2026-10-08T19:37:10",8,"*летя вплотную к растениям, ищет клевер. Возможно, попадётся 4-листный, но хватит и радужного*",260944,null],[262132,"2026-10-08T19:37:19",8,"/roll 1d20",260944,null],[262134,"2026-10-08T19:37:29",58,"//невезунчик",262129,null],[262136,"2026-10-08T19:37:39",38,"Сумрак собирает очень осторожно и используя свою демоническую руку (Заклинание волшебная рука)",262125,null],[262137,"2026-10-08T19:37:46",38,"/roll@roll_bot",260944,null],[262139,"2026-10-08T19:38:00",58,"михуил максимально акуратно старается все собрать",262127,null],[262142,"2026-10-08T19:38:46",8,"*если найдёт, вырывает двумя руками, чтобы сподручнее*",262130,null],[262143,"2026-10-08T19:38:49",59,"Молодой пацанёнок в горничной одежде оправдывает свои возможности аккуратно собирая возможные нужные травки, подмечая какие-то новенькие но при этом очень неаккуратно подтверждает какие-то маленькие травки и и + дополнительно находит необычный растения с интересным запахом 🌿 переливается ярким синеватым светом*",262126,null],[262151,"2026-10-08T19:40:48",59,"*Феечка, порхая своими крылышками, подлетает к скрытым местам среди деревьев, где находит почти идеальный клевер. Его лепестки — однолистные, двухлистные, а иногда и трехлистные — переливаются радужным светом. Своими маленькими ручками она ловко собирает эти прекрасные цветы. Это просто невероятно! И при этом замечает когда вырывает клеверы интересные наросты из земли как корни без основания травы",262130,null],[262161,"2026-10-08T19:44:20",8,"/roll 1d20+3 природа на наросты",260944,null],[262163,"2026-10-08T19:44:30",8,"/+2, но ладно",260944,null],[262164,"2026-10-08T19:44:36",59,"*А параноик-мальчик в масочке аккуратно срывает своими волшебными ручками отдалённо разные травки разных цветов, но его больше всего привлекают необычные зеленоватые структуры, которые выплёскивают небольшие частицы неподалёку от своих листьев, пыльцу, которая, попадая на его ручку, даёт странные ощущения, которые никак не вредят только вызыва необычное чувство желание закурить им.  *",262136,null],[262166,"2026-10-08T19:45:46",38,"Сумрак сразу же стряхивает эту пыльцу и говорит.\n— Мне кажется... Или я догадываюсь что это за пыльца...",262164,null],[262167,"2026-10-08T19:45:57",59,"*Феечка подходит ближе к загадочным наростам, пытаясь понять, что это такое. Но, видимо, она не очень много читала о растениях. Она осознает, что перед ней необычное растение, лишенное стебля. Это растение не поглощает солнечный свет как другие растения обычные, но каким-то образом умудряется выжить на земле, что вызывает интерес. Удивительно, как такое возможно в столь необычном месте .*",262163,null],[262168,"2026-10-08T19:46:05",58,"-говоряй",262166,null],[262175,"2026-10-08T19:48:38",59,"*Наша группа исследователей наткнулась на различные растения и, по всей видимости, погрузилась в глубокие размышления.*",260944,null],[262176,"2026-10-08T19:48:57",8,"/сейчас выпаду на полчаса",260944,null],[262177,"2026-10-08T19:49:41",59,"//ну ты можешь магический анализ скинуть если хочешь",262166,null],[262179,"2026-10-08T19:50:11",38,"Сумрак — Это похоже на то, что добавляют в табак...",262168,null],[262181,"2026-10-08T19:50:38",58,"-хм тобишь ты предлагаешь нам обкуриться",262179,null],[262182,"2026-10-08T19:50:42",58,"-я только за",260944,null],[262183,"2026-10-08T19:51:06",38,"Сумрак — Наоборот говорю быть осторожнее...",260944,null],[262196,"2026-10-08T19:55:22",59,"*юный горничный мальчик хочет попробовать интересный косяк трын травы*",260944,null],[262197,"2026-10-08T19:55:35",59,"*опиши, как ты хочешь закурнуться*",260944,null],[262200,"2026-10-08T19:56:22",58,"//не я сохраню это на будуйщее",260944,null],[262204,"2026-10-08T19:57:18",59,"*юное дарование магическое, видимо, решает потом при помощи своего анализа или у алхимика спросить про травку и прячет свои закорки под свою юбку травку.",260944,null],[262206,"2026-10-08T19:57:57",59,"// так же вы собрали нужное количество ингредиентов",260944,null],[262207,"2026-10-08T19:58:21",38,"// Все?",262206,null],[262209,"2026-10-08T19:58:27",58,"-ну все пошлмте к деду",260944,null],[262210,"2026-10-08T19:58:30",59,"*так то ещё не хотите забрать что то дополнительно что я до этого описывал*",260944,null],[262211,"2026-10-08T19:58:49",59,"*или например ещё порыскать*",260944,null],[262212,"2026-10-08T19:58:53",38,"Сумрак встал во весь рост и потянувшись посмотрел на время суток.",260944,null],[262214,"2026-10-08T19:58:59",59,"//на ваше усмотрение",262207,null],[262217,"2026-10-08T20:00:26",59,"* среднего роста юноша вставая весь рост смотрит наверх и видит что уже дней а вы пришли ранним утром, когда даже не было солнца, потратили 5 часов на сборы довольно быстро сделали 1 поручение из 3 и к сожалению без приключений слишком осторожный*",262212,null],[262220,"2026-10-08T20:01:26",38,"// Рост сумрака 175 см и он Юноша",262217,null],[262222,"2026-10-08T20:01:48",38,"// А не маленький мальчик",260944,null],[262229,"2026-10-08T20:03:18",38,"\"Итого... Осталось ещё два поручения\"\nСумрак решает посмотреть, есть ли что-то ещё интересное или полезное для себя.",262217,null],[262236,"2026-10-08T20:03:44",59,"/ты хочешь поискать что то новенькое или из что вы недавно нашли посмотреть",262229,null],[262242,"2026-10-08T20:04:51",38,"// Что-то новенькое",262236,null],[262243,"2026-10-08T20:05:23",59,"//прошу прокинуть на выживание",262242,null],[262246,"2026-10-08T20:06:07",58,"-ну вроде не сложно но заебисто",262229,null],[262250,"2026-10-08T20:06:23",38,"/r +d20+4 Думаю фея мне поможет",262243,null],[262253,"2026-10-08T20:06:23",58,"//всем или ток 1?",262243,null],[262259,"2026-10-08T20:07:13",59,"//но только для него он же 1 хочет, по-моему, и ты, если хочешь тоже можешь кидать Что-то новенькое поискать пока что есть на что посмотреть.",262253,null],[262262,"2026-10-08T20:08:01",59,"*подходя к дереву юноша присматривается и видит необычный плющ который покрыт необычной энергетикой которая веет холодом",262250,null],[262264,"2026-10-08T20:08:40",38,"Сумрак наклоняет голову и положив растения к себе в карманы демонической рукой берет плющ",262262,null],[262265,"2026-10-08T20:09:25",59,"//кто то ещё хочет что то поискать, также можете кинуть на анализ чтобы попробовать что то понять что вы такое нашли",260944,null],[262270,"2026-10-08T20:11:58",59,"//ладно, пока что подожду ваших заявок, я пойду немножко перекушу.",260944,null],[262273,"2026-10-08T20:13:49",58,"/r d20+6 михуил решил проверить что за травы такие он собрал",260944,null],[262280,"2026-10-08T20:18:25",8,"/ещё через полчаса точно буду",260944,null],[262304,"2026-10-08T20:41:31",59,"*Видимо, у горничной не так всё было хорошо с анализом магических травок, но он понимает, что травка, которую он взял и спрятал в своей юбке, достаточно интересная и безвредная, что будет интересно вызывать «Закурнуть». И ещё та травка, которую он до косяка нашел, интересно переливается частицами голубоватого цвета, и ощущаются тёплые ощущения.*",262273,null],[262305,"2026-10-08T20:45:31",58,"//хм интересно",262304,null],[262306,"2026-10-08T20:46:19",8,"/тут",260944,null],[262307,"2026-10-08T20:47:08",59,"//хорошо, ты что-то будешь делать? Или хватило у вас приключений😂 и осторожность не позволяет продолжить? 😁",262306,null],[262309,"2026-10-08T20:47:56",8,"*вырываю один корешок*",260944,null],[262310,"2026-10-08T20:48:09",59,"//Попрошу атлетику",262309,null],[262311,"2026-10-08T20:48:34",8,"/roll 1d20-1 силой воли живём",260944,null],[262313,"2026-10-08T20:48:42",8,"/не живём",260944,null],[262314,"2026-10-08T20:49:07",59,"**феечка тужись, тужись только еле, как немножко припонимает наростик*",260944,null],[262317,"2026-10-08T20:50:45",58,"//мощно",262312,null],[262318,"2026-10-08T20:51:46",8,"*прицепляю к корню верёвку, перекладываю её на любую горизонтальную ветку и тяну*",260944,null],[262319,"2026-10-08T20:52:02",59,"//ну, можешь попросить помощи у товарищей?",262318,null],[262320,"2026-10-08T20:52:29",38,"Сумрак, заметив действия феи, решил помочь ей.",260944,null],[262321,"2026-10-08T20:52:32",59,"//хотя мне нравится твоя идея может с преимуществом и без своего модификатора, который уменьшают кидать.",262318,null],[262322,"2026-10-08T20:52:46",38,"// Помощь",262320,null],[262323,"2026-10-08T20:52:51",8,"/roll +d20",260944,null],[262325,"2026-10-08T20:53:09",8,"– Спасибо, Сумрак",260944,null],[262327,"2026-10-08T20:53:36",38,"— Обращайтесь мисс...\nСумрак похоже забыл имя феи или она не представлялась.",262325,null],[262328,"2026-10-08T20:54:06",8,"– ...Майа Бз-Бз",260944,null],[262329,"2026-10-08T20:54:25",38,"— Майа, красивое имя для такой феи, как вы.",262328,null],[262331,"2026-10-08T20:54:38",59,"*Феечка необычным образом смогла вытянуть на ростик, и со звуком «чпок» вылетает наростик, и также на его стеблях этого корня парочку шариков мстистым запахом.*",260944,null],[262333,"2026-10-08T20:55:10",8,"*сворачиваю верёвку и складирую корень*\n– Знаю, согласна",262329,null],[262335,"2026-10-08T20:57:38",59,"*Возможно, наша команда исследователей захочет узнать что-то новое, попробовать свои силы в чём-то ещё, проанализировать что-то необычное или заняться чем-то другим.*",260944,null],[262336,"2026-10-08T20:58:05",8,"/надо остальных дождаться тогда",260944,null],[262339,"2026-10-08T20:59:02",8,"/пока грибы ядовитые поищу/",260944,null],[262343,"2026-10-08T21:00:12",59,"//пожалуйста, в студию выживания",262339,null],[262344,"2026-10-08T21:01:15",8,"/roll 1d20",262343,null],[262346,"2026-10-08T21:03:38",59,"*Среди многообразия растений, словно по воздуху, порхает фея, тщетно пытаясь отыскать грибы. \n\nНаконец, её взору предстают необычные, на её взгляд, ядовитые грибы: \n\n1. Очень мелкий грибочек с синей шляпкой, покрытый зелёным налётом. \n2. Другой грибочек, тёмный и чёрный, словно гниющий, но с каким-то странным притягательным и манящим ароматом.",260944,null],[262348,"2026-10-08T21:05:21",8,"*надеваю перчатки и складирую обоих в ведро*",262346,null],[262352,"2026-10-08T21:07:49",59,"//ну если вы все сделали можете возвращаться к старику и бежать по 2 поручению",260944,null],[262353,"2026-10-08T21:08:08",59,"//наверное квест на 1 этапе кажется вам скучным на 2 надеюсь хотя бы что то получится",260944,null],[262358,"2026-10-08T21:10:55",8,"/я выпала, большинство разошлось. Надо собраться, и всё ок/",260944,null],[262361,"2026-10-08T21:11:08",58,"иду к деду",260944,null],[262364,"2026-10-08T21:12:15",59,"*маленький фембойчик горничная пошла к деду в одиночку а что же остальная партия готова ли продолжать*",260944,null],[262365,"2026-10-08T21:12:27",38,"Сумрак тоже начинает идти к алхимику.",260944,null],[262373,"2026-10-08T21:15:10",8,"*летит с ведром в руке",260944,null],[262375,"2026-10-08T21:15:57",59,"*Отряд приключенцев отправляется к дедку уже подходя к его избушке через час*",260944,null],[262377,"2026-10-08T21:16:56",38,"Сумрак снова случиться в дверь и говорит.\n— Дедуль, мы пришли с тем, что вы просили...",260944,null],[262386,"2026-10-08T21:18:42",8,"– И по мелочи немного",260944,null],[262401,"2026-10-08T21:22:41",59,"– Молодцы, ря..детишки Хотя вам стоило быть более аккуратными при сборе травы, вы собрали достаточное количество.",260944,null],[262402,"2026-10-08T21:23:12",59,"*старичок начинает перебирать нужные ингредиенты, которые вы собрали Оценивать тщательно*",260944,null],[262406,"2026-10-08T21:25:48",8,"– Извините, старик. А яды не варите?",260944,null],[262409,"2026-10-08T21:26:18",59,"– О, дорогая внученька, конечно, я алхимик и кое-что понимаю в ядах.",262406,null],[262412,"2026-10-08T21:26:48",38,"Сумрак стоял и о чем-то размышляя ходил по комнате, стараясь никому не мешать.",260944,null],[262418,"2026-10-08T21:28:36",8,"*придвинула ему ведро*\n– Не можете из них что-нибудь... Ядовитые они на вид. Я заплачу, сколько надо",262409,null],[262430,"2026-10-08T21:33:49",59,"Интересные грибочки ты нашла, маленькая внученька.\nПервый грибочек — «мебелиозная кашрул», из него можно приготовить яд, который может заменить эффект яда, заставляя цель упасть без сознания, ну или другой вариант — сделать из него слабительный.\nА 2 грибочек называется «психогорорай чигнски», этот грибочек необычен, при помощи него вполне можно изготовить яд психического действия, которая может вызвать головокружение и ошеломление, нанося ему галлюцинации, или в паре с радужным клевером при правильной варке холодный или горячий эффект галлюцинаций",262418,null],[262437,"2026-10-08T21:35:45",59,"–что же внученька это почти обычные хоть и редко  грибочки могу сделать тебе яд всего лишь то за 28 зм",260944,null],[262438,"2026-10-08T21:36:15",38,"Сумрак тоже достает из своих карманов разные травы и говорит.\n— Вот у меня тоже интересные, мне они не так сильно нужны, но возможно сойдут для чего-то",260944,null],[262439,"2026-10-08T21:36:20",8,"*положила 28* – Благодарю",262437,null],[262440,"2026-10-08T21:36:33",59,"//ну, кажись, одобрении получили эти яды от харда, я ему только что написал Насчёт этих хмбрю хотя некоторые хб",260944,null],[262441,"2026-10-08T21:37:12",59,"– Внученька, я могу создать несколько разновидностей этого яда, как я уже рассказывал тебе. Их будет достаточно для нескольких доз, выбирай любую, какая тебе нравится.",262439,null],[262443,"2026-10-08T21:37:25",58,"а михуил держит свои травы при себе пока что",260944,null],[262446,"2026-10-08T21:39:06",8,"– Бессознательный. Другой – ошеломительный. Получится?",262441,null],[262450,"2026-10-08T21:40:41",8,"– Чем ещё подсобить?",260944,null],[262453,"2026-10-08T21:41:12",59,"Мне кажется, ты собрали только те травки, которые были нужны для вашего квеста. Но вы не собрали новые травы, которые я вам предлагал. Возможно, вы что-то упустили или собрали не все. Не могли бы вы напомнить, какие травы вы взяли?",262438,null],[262454,"2026-10-08T21:42:03",59,"— Не нужно, внученька. Сейчас я быстро сварю тебе ягоду. Думаю, ты не против, если я возьму несколько штук себе на сушку? Не зря же я купил хороший котёл, чтобы всё готовить быстро.",262450,null],[262455,"2026-10-08T21:42:48",59,"//извините не посмотрел как там исправлял меня Т9",262453,null],[262456,"2026-10-08T21:43:05",8,"/три задания же?",262454,null],[262459,"2026-10-08T21:43:23",59,"//да осталось только два",262456,null],[262466,"2026-10-08T21:44:06",59,"*старичок начинает быстренько шевелить своими руками зажигая магический алхимический огонь бросая грибочки и начиная танцы с бубном* –тумба юмба хкемс бунда сая банкуй хура",260944,null],[262469,"2026-10-08T21:44:39",38,"// Вот",262164,null],[262472,"2026-10-08T21:45:27",59,"//понятно значит помимо нужно необходимой травы  так же как и какие горничный мальчик взял косяк?",262469,null],[262473,"2026-10-08T21:45:48",59,"//а да ещё плющ сейчас закончу с ядом и тебе скажу.",260944,null],[262477,"2026-10-08T21:45:51",38,"// Все забрал и все отдал прямо здесь",262472,null],[262481,"2026-10-08T21:46:13",58,"//а горничный мальчик имя потерял?",262472,null],[262484,"2026-10-08T21:46:42",58,"//или так веселее",262481,null],[262497,"2026-10-08T21:49:14",59,"*доварив в яд старичок выставляет перед феечка 5 стеклянок*\n–держи маленькая внученька вот этих 2 баночках яд бессознательный он зеленоватого цвета с полосками синего цвета.\nА в остальных 3 которые сияют черноватым оранжевыми спохами находится находится яд наркотическими действиями который вызывает галлюцинация эффектом  ошеломления ( короче яд вызывает состояние которое ошеломляет и так же наносит 1d4 психического урона на 5 раунде делай жертву более восприимчивую к внушению)",260944,null],[262499,"2026-10-08T21:49:33",59,"//да так по приколу называем Михаила так",262481,null],[262504,"2026-10-08T21:51:43",59,"– Давай посмотрим, что ты нашёл, внучок. А ты нашёл интересный предмет — псевдо траву «косяк трин трава». Это растение высокой редкости, обладающее необычными свойствами, если его закорнуть.\n\nТакже в твоём распоряжении оказался плющ — растение, которое можно найти в нашем лесу, хотя и в обычных местах. Этот плющ растёт в холодных зонах и может заменить ядовитый урон на холодный в различных ядах.",262438,null],[262505,"2026-10-08T21:52:13",8,"– Хорошо на стрелы пойдёт *взвесила в руке и убрала* *ждёт задания*",260944,null],[262509,"2026-10-08T21:56:27",38,"Сумрак немного подумал и ответил.\n— Тогда вы можете взять его... Мне нету никакой пользы в этом всем...",262504,null],[262512,"2026-10-08T21:57:04",59,"–хорошо внучок тогда готовы ли вы к моему 2 поручению?",262509,null],[262515,"2026-10-08T21:58:12",8,"– Ага. Надо пострелять в кого?",260944,null],[262516,"2026-10-08T21:58:36",58,"-конечно",262512,null],[262517,"2026-10-08T21:58:41",59,"–Нет, конечно, внученька, а ты кровожадная, кмх-кмх",262515,null],[262518,"2026-10-08T21:59:16",59,"— У меня есть знакомый, которому нужна ваша помощь. Взамен он передаст вам то, что мне необходимо для выполнения вашего третьего поручения.",260944,null],[262519,"2026-10-08T22:00:11",8,"/@STR_V_Alekseev, ещё не засыпаешь?/",260944,null],[262522,"2026-10-08T22:01:36",8,"/у него режим несвергаемый, иногда вырубает. Вот и спрашиваю",260944,null],[262525,"2026-10-08T22:02:15",59,"//интересно кое что новое узнал про Дениса",262522,null],[262528,"2026-10-08T22:04:51",59,"//если что что я вам скажу вы уже почти большую половину квеста прошли",260944,null],[262529,"2026-10-08T22:05:09",59,"/ Fantomas @iakukot вы завтра во сколько сможете если конечно получится",260944,null],[262530,"2026-10-08T22:06:22",8,"/без понятия, могут быть форс-мажоры, но надеюсь не совсем ночью. Скорее всего, в любое время/",262529,null],[262532,"2026-10-08T22:09:39",58,"//я могу после 3 пары тобишь",262529,null],[262533,"2026-10-08T22:09:58",58,"//16 30 по мск",260944,null],[262534,"2026-10-08T22:11:16",59,"//ладно если  сейчас Денис не появится через 20 минут то я наверное лягу спать если что заранее всем спокойной ночи и надеюсь завтра сможем завершить",260944,null],[263181,"2026-10-09T09:43:28",59,"*Услышав просьбу одного старика, команда искателей приключений отправилась на поляну, где  возможно ждёт знакомый старика, которому надо помочь.*",260944,null],[263759,"2026-10-09T14:53:20",59,"/// так значит только ждём @iakukot",260944,null],[263762,"2026-10-09T14:54:29",58,"//я впринципи на паре щяс могк",263759,null],[263768,"2026-10-09T14:55:25",59,"// @iakukot Fantomas  @STR_V_Alekseev",263181,null],[263772,"2026-10-09T14:56:28",58,"-я думал нам только тебе помогать придется",263181,null],[263774,"2026-10-09T14:56:43",38,"Сумрак шел смотря себе под ноги и спросил у феи с человеком.\n— Он сказал, как он выглядит?",263181,null],[263786,"2026-10-09T14:58:21",59,"*получила только информацию куда им надо прийти на полянку в котором их ожидает возможно знакомы в это время сидеть*",263774,null],[263788,"2026-10-09T14:58:59",8,"– Увы, нет. Стоило спросить",263774,null],[263800,"2026-10-09T15:02:29",59,"*команда приключенцев переговариваясь между собой идёт к этой полянке*",260944,null],[263805,"2026-10-09T15:03:40",58,"-мда что делать щяс будем?",260944,null],[263810,"2026-10-09T15:04:34",38,"— Идти к поляне... Думаю это не будет так сложно...\n Сумрак ушел обратно в свои мысли и начал идти по указанному маршруту.",260944,null],[263819,"2026-10-09T15:05:42",59,"//подождите пару минут сейчас перекушу пюре*",260944,null],[263874,"2026-10-09T15:16:19",58,"//приятного",263819,null],[263881,"2026-10-09T15:16:47",59,"//спасибо а то с утра до пары ничего не покушал хотя бы когда приехал покушал пюре и компот",263874,null],[263890,"2026-10-09T15:17:47",59,"*когда наш отряд приключенцев вышел на поляну, то увидел двухметрового мускулистого гуманоидного волка, который ковырялся в зубах зубочисткой.*",260944,null],[263894,"2026-10-09T15:18:20",59,"*заметив ваше присутствие волк потирает живот и говорит*\n–ох опять охотник, у меня уже изжога начинается",260944,null],[263901,"2026-10-09T15:18:55",58,"-мы с миром но готовы защищяться",260944,null],[263909,"2026-10-09T15:20:52",38,"Сумрак поднял голову на волка и спросил.\n— Вы знакомый алхимика?",260944,null],[263919,"2026-10-09T15:22:38",8,"– Охотники мы по обстоятельствам. Сейчас вот мелкие поручения выполняем",263894,null],[263921,"2026-10-09T15:23:42",59,"–А хлопцы, вы от старика, что вы молчали так, я уже думал, сейчас придётся мучиться, изжогой в животе",263909,null],[263925,"2026-10-09T15:25:45",59,"–Ладно, хлопцы, вы, наверное, по просьбе старика, чтобы я дал особый товар",260944,null],[263926,"2026-10-09T15:25:54",59,"–Ну ради этого  немножко придётся поработать",260944,null],[263927,"2026-10-09T15:26:16",58,"-снова работать?",260944,null],[263928,"2026-10-09T15:26:46",38,"Сумрак провел своей рукой вдоль маски и спросил.\n— Что именно от нас требуется?",260944,null],[263929,"2026-10-09T15:26:49",8,"– Неудивительно. Бесплатный сыр только в мышеловке *хмыкнула, сложив руки*",263926,null],[263930,"2026-10-09T15:27:25",59,"///сейчас на пару минут надо выйти улицу после этого я надеюсь смогу уделить время для вас и меня не будут отвлекать",260944,null],[263990,"2026-10-09T15:43:20",59,"–что же ребята нужно провести контраперехват ценного груза.",263928,null],[263997,"2026-10-09T15:44:19",8,"– Кто его везёт? Груз живой? Насколько опасный?",263990,null],[263998,"2026-10-09T15:44:27",58,"-поточнее можно \n*вопросительно посмотрел михуил*",263990,null],[264006,"2026-10-09T15:45:05",59,"–какой живой груз надо всего лишь то корзиночку перехватить малышка.",263997,null],[264013,"2026-10-09T15:45:43",8,"/о нет, а как же бабушка без пирожков",260944,null],[264014,"2026-10-09T15:45:45",38,"Сумрак — Дай угадаю... У ребенка в красном?",264006,null],[264016,"2026-10-09T15:45:54",58,"-звучит легко",264006,null],[264020,"2026-10-09T15:46:44",58,"//я один кажись не понимаю отсылку...",260944,null],[264021,"2026-10-09T15:46:49",59,"–нет не красным",264014,null],[264023,"2026-10-09T15:46:55",38,"// Красная шапочка",264020,null],[264024,"2026-10-09T15:46:59",8,"– Мы ограбим голодного ребёнка? Это этично?",264014,null],[264026,"2026-10-09T15:47:20",59,"–мы никого не будем ограблять мы делаем всего лишь то контур перехват через мои территории здесь так то граница",264024,null],[264027,"2026-10-09T15:47:27",38,"— Я не буду этого делать... Я еще не стал настолько безумцем, чтобы делать это...",264024,null],[264029,"2026-10-09T15:47:42",58,"//вырос чутка в друго культуре так сто поже разберусь мб",264023,null],[264031,"2026-10-09T15:48:10",58,"-Хм а как вы определяете границы",264026,null],[264033,"2026-10-09T15:48:12",59,"–кто несёт груз конечно я не знаю но  точно не ребёнок",264027,null],[264035,"2026-10-09T15:48:27",8,"– А для этого обязательно отбирать груз? Что он представляет?",264026,null],[264041,"2026-10-09T15:48:57",59,"–ну можно можно не отбирать ну попробуйте договориться я не против",264035,null],[264046,"2026-10-09T15:49:25",8,"– Какова цель: отпугнуть или забрать товар?",264041,null],[264047,"2026-10-09T15:49:29",59,"–корзиночка с накрытом платком по судя, по информации моей, которую мне предоставили там ценный груз.",264035,null],[264049,"2026-10-09T15:49:44",59,"–малышка конечно товар",264046,null],[264052,"2026-10-09T15:50:54",8,"– Попробуем разобраться в процессе, или кто-нибудь изначально против? *смотрит на сокомандников*",260944,null],[264058,"2026-10-09T15:51:56",58,"-мне безразницы",260944,null],[264060,"2026-10-09T15:52:54",38,"Сумрак — Если это не ребенок, то я участвую.",260944,null],[264063,"2026-10-09T15:53:35",59,"–да я хвост съем если вам покажется что такое ценный груз будет перевозить ребёнка слабый",264060,null],[264068,"2026-10-09T15:55:10",8,"– Ладно, где приблизительно пролегает маршрут перевозчика?",260944,null],[264078,"2026-10-09T15:56:53",59,"*волк встаёт восточную сторону указывает пальцем в 1 из больших деревьев в котором растут яблоки треугольный формый*\n–по моим источникам груз должен переходить через тот маршрут возле того дерева и напоследок говорю вам, не всегда доверяйте своему зрению.",264068,null],[264093,"2026-10-09T15:59:43",58,"-понятно записал",264078,null],[264095,"2026-10-09T16:02:27",8,"*скрылась в кусты рядом и наблюдает*",260944,null],[264096,"2026-10-09T16:02:38",8,"/roll 1d20+3 я зелень",260944,null],[264099,"2026-10-09T16:03:27",59,"*Феечка летает между кронами, но не умела, слишком уж выделяется ее бз-бз и жёлтый цвет.*",260944,null],[264101,"2026-10-09T16:03:37",8,"/везунчик использовала",260944,null],[264102,"2026-10-09T16:03:45",58,"/r +4 Михуил спрятался за дереаом",260944,null],[264106,"2026-10-09T16:06:36",59,"*что же наши проключенцы только двое решили хорошенько спрятаться в корнях а наш юноша в маске решил стоять в лоб *",260944,null],[264111,"2026-10-09T16:08:48",59,"*стоя в ожидании в засаде вы начинаете слышать звуки шагов*",260944,null],[264114,"2026-10-09T16:09:40",8,"*рассматривает втихую чудо-юдо* /кидать что-нибудь?",260944,null],[264117,"2026-10-09T16:10:32",59,"//это не красная шапка а алая шапка и не забывайте слова волка (не стоит делать поспешных выводов не все так просто)",260944,null],[264119,"2026-10-09T16:11:10",8,"/не блестят ли её глаза? Дин говорил, это признак оборотня",260944,null],[264120,"2026-10-09T16:11:17",38,"Сумрак, что стоял не скрываясь спросил, находясь в страшной маске.\n— Мисс, куда вы держите курс?",264117,null],[264122,"2026-10-09T16:11:32",58,"//если я хуйню магичискими стрелами в нее это будет хорошей идеей?",260944,null],[264123,"2026-10-09T16:11:38",38,"// Нет",264122,null],[264127,"2026-10-09T16:12:18",59,"–Я?.. Несу корзинку ягод",264120,null],[264130,"2026-10-09T16:12:43",38,"— Ох... Тогда прошу вас показать ягоды, что вы несете... Лесная инспекция.",264127,null],[264138,"2026-10-09T16:14:26",59,"*Сразу серипеет алая шапа и из ниоткуда вырастает длинный коса больше её роста*\n\n–ах вы уроды хотите сточить корзинку с пирожками, какая ещё лесная пограничники да я вас порву",260944,null],[264143,"2026-10-09T16:15:34",58,"//а вот теперь волшебные стрелв это хоршая идеч?",260944,null],[264146,"2026-10-09T16:15:37",38,"— А я говорил что это красная шапочка, про которую я слышал...\n Отвечает Сумрак вспоминая её версию из издания Солнечного затмения.\n— Мистер Михаил, прошу помочь...",264138,null],[264147,"2026-10-09T16:15:52",59,"//вообще то не красная а алая шапочка",264146,null],[264149,"2026-10-09T16:16:12",59,"//r d20+1 куда спешим без инициативы",260944,null],[264150,"2026-10-09T16:16:22",59,"/r d20+1 куда спешим без инициативы",260944,null],[264154,"2026-10-09T16:16:45",38,"// Разницы не имеет. Алый это оттенок красного",264147,null],[264155,"2026-10-09T16:16:47",8,"/roll 1d20+3 инициатива (преимущество на удар из засады)",260944,null],[264157,"2026-10-09T16:16:53",58,"//у меня же есть доп действие от засады",260944,null],[264158,"2026-10-09T16:17:04",58,"/r 4d4+4",260944,null],[264160,"2026-10-09T16:17:12",38,"/r +1 Инициатива",260944,null],[264162,"2026-10-09T16:17:28",58,"/r +2 инициатива",260944,null],[264165,"2026-10-09T16:17:50",59,"// инн.\nФея 23\nАлая шапочка 17\nСумрак 16\nМаг 14",260944,null],[264167,"2026-10-09T16:18:38",58,"//как обычно у меня самая низкая инициатива",264165,null],[264171,"2026-10-09T16:18:59",59,"//ну насколько разный оттенок в какой то степени относится к сожалению откуда я её взял",264154,null],[264174,"2026-10-09T16:19:08",8,"/roll +d20-1 ныа из лука",260944,null],[264178,"2026-10-09T16:19:38",8,"/roll 1d20+3 засада",260944,null],[264180,"2026-10-09T16:19:43",8,"/ход",260944,null],[264198,"2026-10-09T16:22:00",59,"*так расстояние между вами такое юноша в маске от шапочки расстояние 15 футов.\nА фея и маг от друг друга 10 футов в отдельный в 45 футов",260944,null],[264206,"2026-10-09T16:22:54",59,"Алая шапочка делает большой рывок к юноше",260944,null],[264208,"2026-10-09T16:23:21",59,"/r d20+5 делает большой размах своей ужасающей косой широко улыбайся",260944,null],[264212,"2026-10-09T16:23:53",58,"//могу везунчиком перекинуть надо дениска?",260944,null],[264216,"2026-10-09T16:25:00",38,"// Кидай уже урон",264208,null],[264219,"2026-10-09T16:25:29",58,"//извиняюсь пара закончилась буду через 10 минут",260944,null],[264222,"2026-10-09T16:26:34",59,"/r 1d8+3 рядущий урон\n/r 1d4 психический",264216,null],[264226,"2026-10-09T16:26:54",38,"// Положило...",260944,null],[264227,"2026-10-09T16:27:03",59,"/ход @iakukot",260944,null],[264228,"2026-10-09T16:27:19",59,"*вы видите как ваш товарищ юноша падает лицом в морду землю*",264226,null],[264233,"2026-10-09T16:27:47",59,"//Денис не спеши пока что",260944,null],[264265,"2026-10-09T16:35:45",58,"//вот почему я не переписал полет у айкора...",260944,null],[264267,"2026-10-09T16:36:19",58,"//и почему я думал что дениска будет танком",260944,null],[264271,"2026-10-09T16:36:46",38,"// У меня кд 11...",264267,null],[264272,"2026-10-09T16:36:51",59,"//у тебя здесь самое большое количество хп",264267,null],[264274,"2026-10-09T16:37:33",58,"//у мага ахуено",264272,null],[264278,"2026-10-09T16:39:03",59,"//не забывай если что у тебя ход",264274,null],[264279,"2026-10-09T16:39:23",58,"//щяс придумаю что то",264278,null],[264283,"2026-10-09T16:40:45",58,"/r 4d4+4 похуй или она нас или мы ее",260944,null],[264285,"2026-10-09T16:41:54",59,"/ход Fantomas  думаю маг все что смог сделал",260944,null],[264290,"2026-10-09T16:44:10",8,"/roll +d20+4 зубочистка из кустов",260944,null],[264292,"2026-10-09T16:44:48",59,"/1 попал",264290,null],[264293,"2026-10-09T16:44:48",8,"/roll 1d6+3+1d6 скрытая атака",260944,null],[264296,"2026-10-09T16:45:10",8,"/roll 1d20+3 в кусты и ход",260944,null],[264298,"2026-10-09T16:45:26",8,"/видно, перекидывать не буду",260944,null],[264300,"2026-10-09T16:45:53",59,"*Шапочка делает резкий шаг в сторону мага приближаясь на 20 футов.",260944,null],[264301,"2026-10-09T16:46:00",59,"/ход @iakukot",260944,null],[264303,"2026-10-09T16:46:13",58,"//какое у меня растояние с ней теперь?",260944,null],[264306,"2026-10-09T16:46:47",59,"/25 футов из изначальных 45 футов",260944,null],[264307,"2026-10-09T16:47:13",58,"//у меня скорость 30 футов мб в догонялки поиграть ?",260944,null],[264310,"2026-10-09T16:47:38",59,"//как хочешь поступай",264307,null],[264312,"2026-10-09T16:47:42",58,"//как тебе идея фея?",260944,null],[264314,"2026-10-09T16:48:01",8,"/если есть тактика, вырази в рп",264312,null],[264315,"2026-10-09T16:48:41",58,"/r 3d4+3 экономлю ячейки",260944,null],[264317,"2026-10-09T16:49:02",59,"//что это?",264315,null],[264319,"2026-10-09T16:49:16",38,"//Маг стрела",264317,null],[264320,"2026-10-09T16:49:19",58,"//стрелы магические первоя ячейка урон",264317,null],[264321,"2026-10-09T16:49:39",59,"/ход Fantomas",260944,null],[264322,"2026-10-09T16:50:24",8,"/сколько до Сумрака?/",260944,null],[264323,"2026-10-09T16:50:36",59,"/45",264322,null],[264324,"2026-10-09T16:51:08",8,"/roll 1d20+4 стрельк",260944,null],[264327,"2026-10-09T16:51:29",8,"/roll 1d6+3+1d6",260944,null],[264329,"2026-10-09T16:51:45",8,"/без [3]",260944,null],[264330,"2026-10-09T16:52:05",8,"/около Сумрака есть кусты?",260944,null],[264331,"2026-10-09T16:52:23",8,"/а высокая трава?",260944,null],[264332,"2026-10-09T16:52:35",59,"/он же вышел на переговоры  на тропинку",264330,null],[264333,"2026-10-09T16:52:46",59,"/только средняя которая укроет твой рост",264331,null],[264335,"2026-10-09T16:52:59",8,"/двигаюсь на 30 к Сумраку. Есть ли на 30 укрытия?",260944,null],[264336,"2026-10-09T16:53:18",59,"/ну для твоего роста конечно всегда найдётся",264335,null],[264337,"2026-10-09T16:53:27",59,"/кроме чистого поляны",260944,null],[264338,"2026-10-09T16:53:37",8,"/roll 1d20+3 прятки в траве",260944,null],[264340,"2026-10-09T16:53:41",8,"/ход",260944,null],[264341,"2026-10-09T16:54:10",59,"Шапочка делает опять широкий шаг к маг на 20 футов оставляя расстояние 5 футов",260944,null],[264342,"2026-10-09T16:54:28",59,"/r d20+5 делает ромашистый удар своей большой косой",260944,null],[264344,"2026-10-09T16:54:38",59,"/ ход @iakukot",260944,null],[264345,"2026-10-09T16:56:00",58,"/r 3d4+3 маг стрелы и потом михуил исчезает в тюмане и появляется в 30 футах от шапочки -ячейка 1 и 2 круга",260944,null],[264348,"2026-10-09T16:56:12",58,"/r 3d4+3",260944,null],[264351,"2026-10-09T16:56:31",59,"/ ход Fantomas",260944,null],[264354,"2026-10-09T16:57:24",8,"*двигаюсь к Сумраку на 15, бонусным вливаю ему зелье и делаю посыл зубочиски*",260944,null],[264355,"2026-10-09T16:57:35",8,"/roll 2d4+2 зелье",260944,null],[264357,"2026-10-09T16:58:01",8,"/roll 1d20+4 стрела летит",260944,null],[264359,"2026-10-09T16:58:12",59,"*Ну что ж, когда ты подходишь и пытаешься влить ему зелье, ты видишь, что юноша просто без сознания, хоть и морды в землю, и что парочка его одежда порвана, особенно часть, где 5 точка.*",264354,null],[264360,"2026-10-09T16:58:20",8,"/roll 2d6+3",260944,null],[264363,"2026-10-09T16:58:51",8,"*тогда убираю зелье и парю рядом*",260944,null],[264366,"2026-10-09T16:58:55",8,"/ход",260944,null],[264374,"2026-10-09T17:01:48",8,"/попытка его растолкать за потраченное бонусное была бы?",260944,null],[264377,"2026-10-09T17:02:22",59,"/да за попытку",264374,null],[264378,"2026-10-09T17:03:01",59,"*алая шапочка в ярости",260944,null],[264384,"2026-10-09T17:04:21",59,"Делать длинный шаг яростный к магу",260944,null],[264387,"2026-10-09T17:04:44",59,"40 футов яростный рывок",260944,null],[264389,"2026-10-09T17:05:32",59,"И яростно подпрыгивает на плечи мага",260944,null],[264390,"2026-10-09T17:05:39",59,"/ @iakukot ход",260944,null],[264396,"2026-10-09T17:06:55",58,"/3d6 огненые ладони",260944,null],[264397,"2026-10-09T17:07:08",58,"/r 3d6",260944,null],[264401,"2026-10-09T17:07:25",58,"//спас ловкости в студию",260944,null],[264402,"2026-10-09T17:07:41",59,"/r d20+1",260944,null],[264404,"2026-10-09T17:07:50",58,"//везунчик",260944,null],[264406,"2026-10-09T17:07:59",58,"//не везунчик спаслась",260944,null],[264407,"2026-10-09T17:08:18",58,"//ход",260944,null],[264409,"2026-10-09T17:08:34",59,"/все? Половину урона получила что с бон дей",260944,null],[264412,"2026-10-09T17:08:57",58,"//а тогда \n/r 3d4+3",260944,null],[264414,"2026-10-09T17:09:12",58,"/r 3d4+3",260944,null],[264416,"2026-10-09T17:09:26",58,"//...",264415,null],[264419,"2026-10-09T17:10:03",59,"/ты бонусным действием можешь что ли использовать волшебный стрелы требуют действия",264412,null],[264425,"2026-10-09T17:11:15",58,"//а разве доп действием нельзя использовать что хочу? если нет то тогда михуил отбегает от нее на 30 футов",264419,null],[264427,"2026-10-09T17:11:36",59,"//заклинание требует разных действий",264425,null],[264428,"2026-10-09T17:11:57",59,"//огненная ладонь же требует твоих действий а бонусные действия это не основное действие только малое количество заклинаний возможно использовать бонусы",260944,null],[264429,"2026-10-09T17:12:11",58,"//все понел запомню",264428,null],[264430,"2026-10-09T17:12:15",59,"/ты не понял это не дополнительное действие а бонусное",264425,null],[264432,"2026-10-09T17:12:44",59,"//ну тебе надо было внимательнее Если ты хочешь бежать без туманного шага тебе бы сначала её скинуть себя",264425,null],[264433,"2026-10-09T17:13:13",58,"//она на мне? тогда не убегаю а щяс что то придумаю",264432,null],[264434,"2026-10-09T17:13:25",59,".",264389,null],[264437,"2026-10-09T17:13:41",59,"//думаю ей не составит труда учитывая что она выше тебя 12 летняя",260944,null],[264438,"2026-10-09T17:14:07",59,"//бля хотя ладно, она же девочка, она лёгкая. Так и задумано было, не надо было проходить проверку на возможность, что ты устоишь из за её веса",260944,null],[264441,"2026-10-09T17:14:58",58,"//огненые ладони отменяются?",260944,null],[264443,"2026-10-09T17:15:22",59,"/зачем ты уже нанёс половину урона",264441,null],[264445,"2026-10-09T17:15:46",59,"/у него же так что если даже пройдёшь то получишь половину",260944,null],[264458,"2026-10-09T17:18:54",59,"/как он в один ход может может использовать два раза",260944,null],[264462,"2026-10-09T17:19:22",59,"/просто он до этого же использовал",264396,null],[264468,"2026-10-09T17:19:41",58,"ну это действие остается и бонусным пытаюсь ее скинуть//",264462,null],[264472,"2026-10-09T17:20:05",59,"/так стоп я запутался",264468,null],[264474,"2026-10-09T17:20:28",59,"/я правильно понимаю что ты не хочешь использовать огненные ладони когда она успешно прошла твой спас",260944,null],[264477,"2026-10-09T17:20:50",58,"//нет я их уже использовал и теперь бонусом пытаюсь ее скинуть",264474,null],[264480,"2026-10-09T17:21:08",59,"/все я понял",260944,null],[264482,"2026-10-09T17:21:32",59,"/извините что я немножко не понял о чем в толково идти не надо было просто повторять я и так засчитал цррн",260944,null],[264484,"2026-10-09T17:22:19",58,"/r -1 атлетика",260944,null],[264488,"2026-10-09T17:22:44",59,"/r d20+1 думаю она использует акробатику чтобы удержать",260944,null],[264490,"2026-10-09T17:22:58",58,"//имба",260944,null],[264493,"2026-10-09T17:23:18",59,"*алая шапочка падает вниз в лоб в камни и теряется сознание*",260944,null],[264495,"2026-10-09T17:23:34",59,"/r 1d6 о камн",260944,null],[264498,"2026-10-09T17:23:53",59,"/молодцы вы ей свернули шею",260944,null],[264499,"2026-10-09T17:24:22",58,"//что такое добрата",260944,null],[264503,"2026-10-09T17:25:18",8,"*прыгает у Сумрака на ладони* – Проснись, маскарадник!",260944,null],[264506,"2026-10-09T17:25:39",58,"*михуил берет алую шапочки и тащит ее с ее вещими к феи и сумраку",260944,null],[264507,"2026-10-09T17:26:20",38,"Сумрак просыпается и сразу попытался встать",260944,null],[264508,"2026-10-09T17:26:23",38,"/r 4d20",260944,null],[264510,"2026-10-09T17:26:29",38,"// Все остались",260944,null],[264512,"2026-10-09T17:27:08",38,"— Что... произошло?\n Спросил юноша осматриваясь и заметив лежащую девушку сказал.\n— Кто это сделал?",260944,null],[264513,"2026-10-09T17:27:31",59,"*каким то чудом изворачиваясь когда он падал лицом об землю наш юноша смог спасти все, что у него было от разреза и возможного сломать свои вещи, конечно, кроме того, что у него штаны возле ж*** порваны даже трусы😂*",260944,null],[264514,"2026-10-09T17:27:38",8,"– Маг. Свернул ей шейку лебяжью",264512,null],[264518,"2026-10-09T17:28:55",58,"-драка была отчайная",264512,null],[264519,"2026-10-09T17:29:25",8,"/roll 1d20 ищет корзинку",260944,null],[264521,"2026-10-09T17:29:38",38,"Заметив свои повреждения одежды Сумрак спросил у мага.\n— Есть заговор починка?",260944,null],[264524,"2026-10-09T17:30:17",59,"*из дерева выходит Волк, который уже кушает из корзины ягодные пирожки.*\n–хлопцы а вы достаточно кровожадные люди ладно прикопайте где-нибудь возле какого то дерева",260944,null],[264525,"2026-10-09T17:30:23",58,"-ну могу что то попробовать сделать если дашь время\n//(формы заговоров если что)",260944,null],[264528,"2026-10-09T17:31:04",8,"– Как на вкус? И чего она тебе сделала?",264524,null],[264529,"2026-10-09T17:31:27",59,"Хорошо, вы сделали часть своей сделки, хотя не стоило до такой крайности, было бы достаточно отвлечь её корзины, но сделка есть сделка",260944,null],[264533,"2026-10-09T17:32:14",8,"– Она угрожала *обиженно скривилась*",264529,null],[264535,"2026-10-09T17:32:20",58,"-ну как вышло так и вышло",264529,null],[264536,"2026-10-09T17:32:35",59,"–очень из вкусной ягоды так и чувствую этот божественный вкус (получается каждый съеденный пирожок который в общем сумме 10 временные хиты в количестве десятки и и подняла ему характеристики на +1 на 15 минут)",264528,null],[264539,"2026-10-09T17:32:58",38,"— Ха... Давай...\n Ответил Сумрак и спросил у Волка.\n— Чтож... Теперь вы сделаете, что требуется от вас, верно?",264525,null],[264542,"2026-10-09T17:33:24",8,"– Копайте, ребят. У меня ямка-хренамка выйдет",260944,null],[264545,"2026-10-09T17:33:50",58,"*михуил садится и пытается придумать заговор для починки одежды *",260944,null],[264548,"2026-10-09T17:34:53",59,"*волк из дерева соседнего достаёт из дупла. Букет и бутылку с надписью \"VIP\"*",264539,null],[264556,"2026-10-09T17:37:03",38,"Сумрак берет это своей демонической рукой и подходит к фее.\n— Ты правда хочешь закопать её? Я могу стабилизировать её и все. Очнется, а нас нету",264548,null],[264561,"2026-10-09T17:38:50",8,"*смотрит на труп* – Для стабилизации потребуется некромант...",264556,null],[264563,"2026-10-09T17:39:21",38,"— Ну у меня есть набор целителя...\nСумрак подходит к девушке и начинает работу",264561,null],[264564,"2026-10-09T17:39:27",38,"/r +4 Медицина",260944,null],[264567,"2026-10-09T17:39:45",58,"//и щяс будет раунд 2",260944,null],[264569,"2026-10-09T17:39:55",38,"// Она проснется через 1к4 часов",264567,null],[264570,"2026-10-09T17:40:03",38,"// По правилам",260944,null],[264571,"2026-10-09T17:40:12",58,"//тогда ладно",260944,null],[264572,"2026-10-09T17:40:19",5,"/ если не померла, на усмотрение мастера",264569,null],[264573,"2026-10-09T17:40:43",38,"// Если умерла, то пусть животное съест",264572,null],[264574,"2026-10-09T17:41:02",59,"*алая шапочка стабилизировалась и её дыхание стабильное хоть и она без сознания сильно приложилась голова*",260944,null],[264575,"2026-10-09T17:41:37",38,"Сумрак встал и сказал.\n— Все, теперь сваливаем...",260944,null],[264576,"2026-10-09T17:41:44",8,"*забирает то и другое себе в рюкзак*",264548,null],[264577,"2026-10-09T17:41:48",58,"*михуил придумал как починить одежду сумрака и подходит к ниму и чинит его одежду*\n//заговор волшебная рука становится починкой",260944,null],[264580,"2026-10-09T17:42:30",58,"-ну теперь пошлите",264575,null],[264581,"2026-10-09T17:42:43",38,"— Спасибо...\n Кивает Сумрак",264577,null],[264583,"2026-10-09T17:42:50",59,"// кто то забывает что на продолжительном отдыхе может поменять заговор",264577,null],[264587,"2026-10-09T17:43:52",59,"//в наказание за то что пытался использовать везунчика и неправильно формулу сделай небольшое наказание",260944,null],[264590,"2026-10-09T17:44:20",58,"//я думал там короткий ну значит не судьба",260944,null],[264591,"2026-10-09T17:44:38",38,"// Не было его",264590,null],[264592,"2026-10-09T17:44:48",38,"// Я стабилизировал за секунды",260944,null],[264593,"2026-10-09T17:44:52",59,"*маг пытаясь туже пытается свернуть свою мозг на износ слишком напрягшись он делает  зловонный пердёж на 40 футов разрывая свои трусы в юбке😂*",260944,null],[264594,"2026-10-09T17:44:57",58,"//",264545,null],[264597,"2026-10-09T17:45:19",59,"//что ж делаем все спас броски на телосложение чтобы выжить под таким зловонным сл 12",260944,null],[264598,"2026-10-09T17:45:34",59,"/r d20+3 волк уже почти начал задыхаться от этого",260944,null],[264601,"2026-10-09T17:45:54",8,"/roll 1d20+2 хотя я не фанат подобного юмора, дм главный",260944,null],[264605,"2026-10-09T17:46:34",38,"/r +2 Спас телосложения",264597,null],[264607,"2026-10-09T17:46:34",8,"/минус второй везунчик",260944,null],[264608,"2026-10-09T17:46:48",59,"*только у юноши не получилось прикрыться от этого зловонья*",264605,null],[264610,"2026-10-09T17:47:14",59,"/r 1d4 вонючего запаха и видимо опять падает у него же почти хп нет😂",260944,null],[264613,"2026-10-09T17:47:53",8,"– Какой мрак *картинно зажала нос рукой*",260944,null],[264617,"2026-10-09T17:51:17",59,"/ @iakukot ты будешь спасаться от своего зловодного запаха которого ты выпустил шпуна?",260944,null],[264618,"2026-10-09T17:51:24",38,"Сумрак упал в этот раз на спину, но успел вытащить зелье лечения в руку, чтобы ему её дали",260944,null],[264620,"2026-10-09T17:52:23",58,"//свое не воняет",264617,null],[264621,"2026-10-09T17:52:51",58,"//дочего мы дошли...",260944,null],[264622,"2026-10-09T17:52:59",8,"*выливает зелье ему*",264618,null],[264623,"2026-10-09T17:53:05",59,"//эм конечно бы я не сказал так ну ладно",264620,null],[264624,"2026-10-09T17:53:59",59,"*ну что же отряд наших приключенцев что же вы будете делать",260944,null],[264625,"2026-10-09T17:54:12",59,"*после очень странного приключения. который я сам, если честно, начал путаться.",260944,null],[264626,"2026-10-09T17:54:16",38,"// Кинь хил зелья",264622,null],[264627,"2026-10-09T17:54:54",8,"/roll 2d4+2",260944,null],[264629,"2026-10-09T17:56:34",8,"– Летим к старику, пока у девочки сознание не прояснилось?",260944,null],[264630,"2026-10-09T17:57:18",38,"Сумрак встает с земли и говорит.\n— Спасибо, Майя... И да, нужно сваливать...",260944,null],[264635,"2026-10-09T18:02:24",58,"//а нам опыт дадут за бой?",260944,null],[264638,"2026-10-09T18:03:02",8,"/давай квест закончим, а там вместе всё🫤",264635,null],[264640,"2026-10-09T18:03:15",59,"/давай закончим у вас вообще прям капля осталась тогда все буду выдавать/",264635,null],[264642,"2026-10-09T18:03:41",58,"//ладно",260944,null],[264643,"2026-10-09T18:03:52",8,"*стучит в дверь* – Тук-тук, мы с гостинцами прилетели!",260944,null],[264650,"2026-10-09T18:06:31",58,"//как вам идея сделать этот квесь и забыть про него?",260944,null],[264653,"2026-10-09T18:07:03",59,"/даже нельзя ничего сказать как Денис сразу начинает материть когда он сам подтвердил что у него хоть и есть признаки я думал ты поймёшь",260944,null],[264654,"2026-10-09T18:07:43",59,"*старичок слышит*",264643,null],[264655,"2026-10-09T18:08:10",59,"-о внучки как вы вовремя принесли  груз",260944,null],[264656,"2026-10-09T18:08:45",58,"-принесли давай 3 задания и все",260944,null],[264657,"2026-10-09T18:09:08",8,"*вынула требуемое* – Вуаля",260944,null],[264658,"2026-10-09T18:10:14",59,"– Хорошо, хорошо, внучочек, прям горишь, моё 3 поручение: не могли вы сходить на северную часть леса и передать эту записку вместе с этим подарком, после этого вы получите зелье",264656,null],[264659,"2026-10-09T18:11:30",8,"– Кого-то на свидание хотите пригласить? /пока Дениса жду/",260944,null],[264660,"2026-10-09T18:12:01",59,"/думаю, вы можете отправляться без него, у него бомбануло, наверное, от моей шутки",264659,null],[264661,"2026-10-09T18:12:25",38,"Сумрак, что плутал разными путями подходит к двери.\n— Так... Я наконец-то вернулся... Что от нас требуется?",260944,null],[264662,"2026-10-09T18:13:09",8,"– Отнести бутылочку да цветы адресату. Леди, полагаю",264661,null],[264663,"2026-10-09T18:13:33",59,"*говорит слишком смышлёная феечка*",264662,null],[264664,"2026-10-09T18:14:12",38,"— Ох... Тогда давайте не будем заставлять леди ждать.\n Ответил Сумрак и отходит с прохода.\n— И затем вы дадите, что просил торговец, верно?",264662,null],[264665,"2026-10-09T18:14:49",8,"*протягивает руку за запиской, убирает товар себе обратно*",260944,null],[264666,"2026-10-09T18:16:00",59,"–да, внучок. Последнее задание",264664,null],[264667,"2026-10-09T18:16:27",58,"-надеюсь будет без приключений а то а устал достаточно сильно",260944,null],[264668,"2026-10-09T18:16:27",59,"*и группа отправляется в северную часть покрытую тёмными зарослями и  зелёными пыльцой*",260944,null],[264671,"2026-10-09T18:17:35",8,"/пыльца обычная?/",260944,null],[264672,"2026-10-09T18:18:24",59,"*спецэффекты/",264671,null],[264675,"2026-10-09T18:19:52",8,"*дышит аккуратнее, странная пыльца*",260944,null],[264676,"2026-10-09T18:21:21",59,"*без приключений вы подходите к маленькой избушечке на окраине обрыва.*",260944,null],[264677,"2026-10-09T18:21:43",59,"*и кто то понимает что он  слишком перенервничал *",260944,null],[264679,"2026-10-09T18:22:37",38,"Сумрак подходит к избушке и стучится в неё.",260944,null],[264680,"2026-10-09T18:23:16",8,"*передаёт ему бутылку, записку и букет*",264679,null],[264681,"2026-10-09T18:23:51",38,"Сумрак берет из и вместе с этим снимает маску показывая свое лицо.",264680,null],[264690,"2026-10-09T18:26:53",59,"*на стук открывает старенькая женщина нежным голосочком*\n–ой молодые люди что вас принесло в столь нелёгкую дорогу",260944,null],[264691,"2026-10-09T18:27:02",58,"*михуил отходит к дереву и ждет пока его друзья сделают всю работу",260944,null],[264693,"2026-10-09T18:27:57",38,"— Здравствуйте, мисс, мы пришли от одного мистера, чтобы вручить вам это письмо...\n Ответил Сумрак протягивая букет, бутылку и письмо.",264690,null],[264694,"2026-10-09T18:29:04",59,"*бабулечка взяла письмо прочитав его у неё появился румянец*\n–ох спасибо маленькие мои, вот возьмите моих сладкие конфеты любит их",260944,null],[264698,"2026-10-09T18:30:42",8,"– Да лёгкая дорога. Вот если бы на нас волки или пироманты напали, другое дело",264690,null],[264700,"2026-10-09T18:31:27",38,"— Не надо мне такого...\n Ответил Сумрак",264698,null],[264701,"2026-10-09T18:31:47",38,"Сумрак — Что вы... Оставьте себе, дадите детишкам помладше...",264694,null],[264703,"2026-10-09T18:32:29",8,"– Она их ему передать хочет, забывчивый Вы наш *села на плечо*",264701,null],[264704,"2026-10-09T18:33:11",38,"— Ха... Снова я не умею понимать речь...\n Ответил парень и взял конфеты.",264703,null],[264708,"2026-10-09T18:35:21",59,"*Бабушка мило улыбнулась вам.*\n– Передать ганграфию, спасибо, что возможно, встретимся скоро, и желаю вам удачи, мои маленькие",260944,null],[264723,"2026-10-09T18:40:06",59,"/как я понимаю вы закончили и отправляйтесь назад*",260944,null],[264725,"2026-10-09T18:40:44",38,"Сумрак поклонился и сказал.\n— До свидания, мисс",264708,null],[264727,"2026-10-09T18:41:28",8,"*делает поклон головой*\n– И Вам успеха во взаимоотношениях)",264708,null],[264729,"2026-10-09T18:41:57",58,"*михуил продалжает сидеть у дерева*",260944,null],[264731,"2026-10-09T18:42:41",59,"*возвращается к деду наша партия без кровия*",260944,null],[264738,"2026-10-09T18:44:02",8,"/ты с нами до деда?",264729,null],[264739,"2026-10-09T18:44:09",58,"//да",264738,null],[264744,"2026-10-09T18:44:49",59,"*старичок уже ждёт вас у крыльца*",260944,null],[264752,"2026-10-09T18:46:13",8,"– Угадайте, что у Сумрака в рюкзаке. Конфеты. Бабушка ваша милая да приятная \n/что там за Санта-Барбара с волком, бабкой и дедом, подумаю/",260944,null],[264755,"2026-10-09T18:47:12",59,"–хорошо, внученька, надеюсь, Изабель понравилась подарок",264752,null],[264756,"2026-10-09T18:47:19",8,"– И как вы подружились с волком, честное слово?",260944,null],[264757,"2026-10-09T18:47:41",59,"–вот как я обещал ваше награда.\n*протягивает вам зелье привилегающее разными цветами радуги*",260944,null],[264758,"2026-10-09T18:47:59",59,"–а сением да делов то было",264756,null],[264759,"2026-10-09T18:48:16",59,"–так то он очень культурный и любитель попить чайка и погонять разные байки",260944,null],[264761,"2026-10-09T18:48:30",59,"–Особенно он обожает ягодные пирожки",260944,null],[264762,"2026-10-09T18:48:49",59,"–кстати за хорошее выполнение задания я вам также сверху добавлю от себя",260944,null],[264764,"2026-10-09T18:49:22",59,"Старичок достаёт из погреба статуэтку собачки которая сразу чувствуется что пропитан магической энергией",260944,null],[264765,"2026-10-09T18:49:47",8,"– Кстати, не думали научиться их печь на пару? А то каждый раз у девчонки отбирать. В перспективе недальновидно",264761,null],[264768,"2026-10-09T18:50:41",59,"–у сения свои замудрешки",264765,null],[264770,"2026-10-09T18:51:24",59,"Эта алебастровая статуэтка становится на 8 часов мастиффом с данными изменениями:\n\n•Размер Крошечный.\n•Атака укусом наносит Колющий урон 1.\n•Мастифф не может сбивать существа с ног.\nЕё нельзя использовать повторно, пока не пройдёт 2 дня.",264764,null],[264771,"2026-10-09T18:51:36",59,"/артефакт обычный редкий",260944,null],[264772,"2026-10-09T18:52:54",59,"Мастиф [Mastiff]\n\nКрошечный? Зверь, без мировоззрения\nКласс Доспеха 12\nХиты 5 (1к8 + 1)\nСкорость 40 футов\nСил\n13 (+1)\nЛов\n14 (+2)\nТел\n12 (+1)\nИнт\n3 (-4)\nМдр\n12 (+1)\nХар\n7 (-2)\nНавыки Восприятие +3\nЧувства пассивное Восприятие 13\nОпасность 1/8 \nОстрый слух и тонкий нюх. Мастиф совершает с преимуществом проверки Мудрости (Восприятие), полагающиеся на слух и обоняние.\n\nДействия\nУкус. Рукопашная атака оружием: +3 к попаданию, досягаемость 5 футов, одна цель. Попадание: Колющий урон 1",264770,null],[264773,"2026-10-09T18:53:51",58,"//это деньги и все как я пониамаю да?",260944,null],[264774,"2026-10-09T18:54:07",59,"/деньги получите когда сдадите зелье торговца",264773,null],[264775,"2026-10-09T18:54:37",58,"//комуто статуя нужна?",260944,null],[264777,"2026-10-09T18:54:58",8,"/нет, забирайте",264775,null],[264780,"2026-10-09T18:55:36",58,"// @STR_V_Alekseev?",264777,null],[264781,"2026-10-09T18:56:45",38,"// Ну мне бы он мог помогать, а так не претендую",260944,null],[264782,"2026-10-09T18:57:02",58,"//забирай тогда",264781,null],[264783,"2026-10-09T18:57:39",59,"*я как понимаю наши отряд приключенцев забирают зелье и не решают себе оставить необычное зелье. Кинуть торговца./",260944,null],[264785,"2026-10-09T18:57:44",38,"Сумрак в основном сидел и слушал. Когда показали статуэтку, юноша решил взять её себе, пусть будет помагать ему.",260944,null],[264786,"2026-10-09T18:58:03",8,"/roll 1d20+1 попытка сравнить лица бабушки и внучки",260944,null],[264788,"2026-10-09T18:58:26",59,"*феечка к своему ужасу понимает, что они очень похожи*",264786,null],[264789,"2026-10-09T18:58:42",58,"//ура я убил чьюто внучку",260944,null],[264791,"2026-10-09T18:59:25",8,"*вывела итоги и прошептала* – Валим, пока дед со старушкой не догадались о том, что мы с внучкой её...",260944,null],[264795,"2026-10-09T19:00:04",8,"/свои зелья забрала. Пойдём за наградой",264783,null],[264796,"2026-10-09T19:00:12",58,"//так мы же ее воскресили",264791,null],[264797,"2026-10-09T19:00:34",8,"/обокрали",264796,null],[264798,"2026-10-09T19:01:17",58,"//хм я ничего плохого в это не вижу она сама первая напала и вырубила дениску",264797,null],[264800,"2026-10-09T19:01:51",38,"Сумрак кивнул и начал идти уже не зажатый",264791,null],[264801,"2026-10-09T19:02:10",38,"// Использую все свои 35 футов ходьбы",260944,null],[264802,"2026-10-09T19:02:28",8,"/я на плече твоём",264801,null],[264803,"2026-10-09T19:02:46",58,"михуил идет за ними думая о том как в теории починить одежду суморка",260944,null],[264804,"2026-10-09T19:03:30",59,".",264783,null],[264805,"2026-10-09T19:03:48",38,"// Забираем конечно",264783,null],[264806,"2026-10-09T19:05:35",59,"//но вы забрали и как я понимаю, и решили кинуть на зелья торговца 😂😂",260944,null],[264807,"2026-10-09T19:06:15",8,"/я нет. Остальные? @iakukot @STR_V_Alekseev",264806,null],[264809,"2026-10-09T19:06:36",38,"// Нет, просто сваливаем из леса к торговцу",264806,null],[264815,"2026-10-09T19:09:16",59,"//что ж поздравляю за завершением задания",260944,null],[264816,"2026-10-09T19:09:27",59,"Вы прибыли отдали торговцу зелье получили 240 зм",260944,null],[264817,"2026-10-09T19:09:32",59,"Сейчас будет опыт",260944,null],[264823,"2026-10-09T19:11:05",59,"Так же за отыгрыш Дениске доп 55 опыта.\nФейчка 60 опыта.\nМихаил 35 опыта.",260944,null],[264824,"2026-10-09T19:11:50",59,"Fantomas @iakukot @STR_V_Alekseev ладно надеюсь что вам хотя бы не вызывает резкого неприязни, а только лёгкое это короткое приключение",260944,null],[264826,"2026-10-09T19:12:37",58,"//а опыт за файт?",260944,null],[264830,"2026-10-09T19:13:16",59,"400 это все вместе",260944,null],[264831,"2026-10-09T19:13:16",59,"С квестом, отыгрышем и опытом за бой*",260944,null],[264832,"2026-10-09T19:13:30",58,"//а с компа не отражается",260944,null],[264834,"2026-10-09T19:14:26",8,"/240 ÷ 3 = 80",260944,null],[264836,"2026-10-09T19:15:18",58,"*михуил зовет сумрака к себе отдыхает ДОЛГО и чинит одежды а потом опять ДОЛГО отдыхает уже 1 и возращяет заговоры на свои места*",260944,null],[264843,"2026-10-09T19:21:54",58,"400 опыта каждому правельно понел или я ебланю?//",264830,null],[264846,"2026-10-09T19:22:02",59,"Да",264843,null],[264847,"2026-10-09T19:22:07",38,"// 400 + за отыгрыш",264843,null]]);
